import{_ as n,o as i,c as a,a3 as r}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"Fragen & Probleme","description":"","frontmatter":{},"headers":[],"relativePath":"referenz/faq.md","filePath":"referenz/faq.md"}'),t={name:"referenz/faq.md"};function s(d,e,h,o,l,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="fragen-probleme" tabindex="-1">Fragen &amp; Probleme <a class="header-anchor" href="#fragen-probleme" aria-label="Permalink to &quot;Fragen &amp; Probleme&quot;">​</a></h1><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><h3 id="ersetzt-shardwing-den-mission-editor" tabindex="-1">Ersetzt Shardwing den Mission Editor? <a class="header-anchor" href="#ersetzt-shardwing-den-mission-editor" aria-label="Permalink to &quot;Ersetzt Shardwing den Mission Editor?&quot;">​</a></h3><p>Nein. Die Mission baust du im Mission Editor – Einheiten, Trigger, Wetter. Shardwing übernimmt die Planung danach: Cartridges, Briefing, Timing, Intel, Kneeboards. Beide arbeiten an derselben .miz.</p><h3 id="welche-flugzeuge-werden-unterstutzt" tabindex="-1">Welche Flugzeuge werden unterstützt? <a class="header-anchor" href="#welche-flugzeuge-werden-unterstutzt" aria-label="Permalink to &quot;Welche Flugzeuge werden unterstützt?&quot;">​</a></h3><p>Cartridges (DTC) für <strong>F-16C</strong> und <strong>F/A-18C</strong>. Alle anderen Flugzeuge siehst du mit Route, Funk, Beladung, Timing und Lineup Card – nur ohne Cartridge.</p><h3 id="welche-karten" tabindex="-1">Welche Karten? <a class="header-anchor" href="#welche-karten" aria-label="Permalink to &quot;Welche Karten?&quot;">​</a></h3><p>Alle DCS-Karten: Caucasus, Syria, Persian Gulf, Sinai, Iraq, Afghanistan, Kola, Germany CW, Nevada, Normandy, Marianas, Falklands. Flugplätze und Bodenstationen sind für alle hinterlegt.</p><h3 id="kostet-shardwing-etwas-brauche-ich-einen-account" tabindex="-1">Kostet Shardwing etwas? Brauche ich einen Account? <a class="header-anchor" href="#kostet-shardwing-etwas-brauche-ich-einen-account" aria-label="Permalink to &quot;Kostet Shardwing etwas? Brauche ich einen Account?&quot;">​</a></h3><p>Nein und nein. Lokal läuft alles auf deinem Rechner; nur zum gemeinsamen Planen braucht es einen Shardwing-Server.</p><h3 id="geht-meine-mission-kaputt" tabindex="-1">Geht meine Mission kaputt? <a class="header-anchor" href="#geht-meine-mission-kaputt" aria-label="Permalink to &quot;Geht meine Mission kaputt?&quot;">​</a></h3><p>Shardwing ändert nur, was du bearbeitest, und lässt den Rest Byte für Byte, wie er war. Die Desktop-App sichert vor jedem Speichern die alte Datei (die letzten 30). Siehe <a href="/dcs/speichern#verlustfrei">Speichern</a>.</p><h2 id="offnen-und-speichern" tabindex="-1">Öffnen und Speichern <a class="header-anchor" href="#offnen-und-speichern" aria-label="Permalink to &quot;Öffnen und Speichern&quot;">​</a></h2><h3 id="die-miz-offnet-nicht" tabindex="-1">Die .miz öffnet nicht <a class="header-anchor" href="#die-miz-offnet-nicht" aria-label="Permalink to &quot;Die .miz öffnet nicht&quot;">​</a></h3><p>Ist es wirklich eine Mission aus dem DCS Mission Editor? Beschädigte oder unvollständige Downloads sind die häufigste Ursache. Die Fehlermeldung unten rechts sagt meist, was fehlt.</p><h3 id="im-browser-landet-„speichern-in-den-downloads" tabindex="-1">Im Browser landet „Speichern“ in den Downloads <a class="header-anchor" href="#im-browser-landet-„speichern-in-den-downloads" aria-label="Permalink to &quot;Im Browser landet „Speichern“ in den Downloads&quot;">​</a></h3><p>Das ist im Browser so (außer Chrome/Edge mit direktem Dateizugriff). Mit der <a href="/start/installieren">Desktop-App</a> speichert Shardwing an Ort und Stelle.</p><h3 id="nach-dem-speichern-im-mission-editor-fehlt-meine-planung" tabindex="-1">Nach dem Speichern im Mission Editor fehlt meine Planung <a class="header-anchor" href="#nach-dem-speichern-im-mission-editor-fehlt-meine-planung" aria-label="Permalink to &quot;Nach dem Speichern im Mission Editor fehlt meine Planung&quot;">​</a></h3><p>Der Mission Editor kann Shardwings Zusatzdatei mit Timing, Callsigns usw. beim Speichern verwerfen. Mehr unter <a href="/dcs/speichern#planungsdaten">Planungsdaten</a>.</p><h2 id="intel-und-cartridges" tabindex="-1">Intel und Cartridges <a class="header-anchor" href="#intel-und-cartridges" aria-label="Permalink to &quot;Intel und Cartridges&quot;">​</a></h2><h3 id="warum-sind-keine-sams-auf-der-karte-meiner-piloten" tabindex="-1">Warum sind keine SAMs auf der Karte meiner Piloten? <a class="header-anchor" href="#warum-sind-keine-sams-auf-der-karte-meiner-piloten" aria-label="Permalink to &quot;Warum sind keine SAMs auf der Karte meiner Piloten?&quot;">​</a></h3><p>Weil Intel zuerst verborgen ist. Gib Stellungen im Bereich <a href="/bereiche/intel">Intel</a> frei.</p><h3 id="die-cartridge-enthalt-keine-threats" tabindex="-1">Die Cartridge enthält keine Threats <a class="header-anchor" href="#die-cartridge-enthalt-keine-threats" aria-label="Permalink to &quot;Die Cartridge enthält keine Threats&quot;">​</a></h3><p><em>Neu aus Route</em> nimmt nur Bedrohungen, die <strong>für diesen Flight</strong> freigegeben sind. Erst freigeben, dann anlegen – oder in der Cartridge im Bereich <em>Threats</em> nachtragen.</p><h3 id="ein-anderer-flight-sieht-unsere-lineup-card-im-kneeboard" tabindex="-1">Ein anderer Flight sieht unsere Lineup Card im Kneeboard <a class="header-anchor" href="#ein-anderer-flight-sieht-unsere-lineup-card-im-kneeboard" aria-label="Permalink to &quot;Ein anderer Flight sieht unsere Lineup Card im Kneeboard&quot;">​</a></h3><p>Eingebettete Kneeboards gelten in DCS pro Flugzeugtyp. Für geheime Unterlagen <a href="/dcs/speichern#export">Export</a> nutzen statt einbetten.</p><h3 id="meine-cmds-programme-wurden-uberschrieben" tabindex="-1">Meine CMDS-Programme wurden überschrieben <a class="header-anchor" href="#meine-cmds-programme-wurden-uberschrieben" aria-label="Permalink to &quot;Meine CMDS-Programme wurden überschrieben&quot;">​</a></h3><p>In der Cartridge war bei CMDS <em>überschreiben</em> an. Standard ist aus – dann behält der Jet deine Programme.</p><h2 id="zeiten" tabindex="-1">Zeiten <a class="header-anchor" href="#zeiten" aria-label="Permalink to &quot;Zeiten&quot;">​</a></h2><h3 id="die-zeiten-sind-um-stunden-verschoben" tabindex="-1">Die Zeiten sind um Stunden verschoben <a class="header-anchor" href="#die-zeiten-sind-um-stunden-verschoben" aria-label="Permalink to &quot;Die Zeiten sind um Stunden verschoben&quot;">​</a></h3><p>Prüfe oben <strong>L/Z</strong> (Ortszeit oder Zulu) und <strong>UTC±</strong> (Zeitzone der Karte). Die voreingestellten Zeitzonen sind Annahmen; korrigierst du sie, wird das mit der Mission gespeichert.</p><h3 id="„die-zeiten-im-mission-editor-passen-nicht-zu-den-geschwindigkeiten" tabindex="-1">„Die Zeiten im Mission Editor passen nicht zu den Geschwindigkeiten“ <a class="header-anchor" href="#„die-zeiten-im-mission-editor-passen-nicht-zu-den-geschwindigkeiten" aria-label="Permalink to &quot;„Die Zeiten im Mission Editor passen nicht zu den Geschwindigkeiten“&quot;">​</a></h3><p>Typisch bei kopierten Routen. Sobald du die Route in Shardwing änderst, werden alle Zeiten sauber aus den Geschwindigkeiten neu gerechnet.</p><h2 id="gemeinsam-planen" tabindex="-1">Gemeinsam planen <a class="header-anchor" href="#gemeinsam-planen" aria-label="Permalink to &quot;Gemeinsam planen&quot;">​</a></h2><h3 id="ein-pilot-hat-seinen-link-verloren" tabindex="-1">Ein Pilot hat seinen Link verloren <a class="header-anchor" href="#ein-pilot-hat-seinen-link-verloren" aria-label="Permalink to &quot;Ein Pilot hat seinen Link verloren&quot;">​</a></h3><p>In der Übersicht unter <strong>Piloten</strong> einen <strong>neuen Link</strong> für seinen Platz erzeugen und ihm schicken.</p><h3 id="ich-will-testen-was-ein-pilot-sieht" tabindex="-1">Ich will testen, was ein Pilot sieht <a class="header-anchor" href="#ich-will-testen-was-ein-pilot-sieht" aria-label="Permalink to &quot;Ich will testen, was ein Pilot sieht&quot;">​</a></h3><p>Oben rechts die Rolle wechseln: <strong>Ansicht als Flight</strong>, Lead oder Wing. Oder den Link in einem privaten Browserfenster öffnen.</p><h3 id="piloten-konnen-nichts-andern" tabindex="-1">Piloten können nichts ändern <a class="header-anchor" href="#piloten-konnen-nichts-andern" aria-label="Permalink to &quot;Piloten können nichts ändern&quot;">​</a></h3><p>Steht die Phase auf <em>Entwurf</em> oder <em>Eingefroren</em>? Und hat der Flight die passenden <a href="/gemeinsam/rollen#freigaben">Freigaben</a>?</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="windows-macos-warnt-beim-ersten-start" tabindex="-1">Windows/macOS warnt beim ersten Start <a class="header-anchor" href="#windows-macos-warnt-beim-ersten-start" aria-label="Permalink to &quot;Windows/macOS warnt beim ersten Start&quot;">​</a></h3><p>Die Installer sind noch nicht code-signiert. Siehe <a href="/start/installieren#download">Installieren</a>.</p><h3 id="wie-bekomme-ich-updates" tabindex="-1">Wie bekomme ich Updates? <a class="header-anchor" href="#wie-bekomme-ich-updates" aria-label="Permalink to &quot;Wie bekomme ich Updates?&quot;">​</a></h3><p>Automatisch: Die App meldet sich unten rechts, wenn es eine neue Version gibt.</p>',45)])])}const g=n(t,[["render",s]]);export{m as __pageData,g as default};
